function formatEffortLabel(label) {
  if (typeof label !== 'string' || !label) return label
  return label.toLowerCase()
}

const normalizedEffortSnapshots = new WeakMap()
function normalizeEffortSnapshot(snapshot) {
  if (!snapshot || typeof snapshot !== 'object') return snapshot
  const cached = normalizedEffortSnapshots.get(snapshot)
  if (cached) return cached
  let changed = false
  const groups = Array.isArray(snapshot.groups)
    ? snapshot.groups.map(group => {
      if (!Array.isArray(group?.models)) return group
      let groupChanged = false
      const models = group.models.map(model => {
        const efforts = model?.reasoning?.efforts
        if (!Array.isArray(efforts)) return model
        let modelChanged = false
        const nextEfforts = efforts.map(effort => {
          const nextName = formatEffortLabel(effort?.name)
          if (nextName === effort?.name) return effort
          modelChanged = true
          return { ...effort, name: nextName }
        })
        if (!modelChanged) return model
        groupChanged = true
        return { ...model, reasoning: { ...model.reasoning, efforts: nextEfforts } }
      })
      if (!groupChanged) return group
      changed = true
      return { ...group, models }
    })
    : snapshot.groups
  const retainedEffort = typeof snapshot.retainedEffort === 'string' ? formatEffortLabel(snapshot.retainedEffort) : snapshot.retainedEffort
  if (retainedEffort !== snapshot.retainedEffort) changed = true
  const result = changed ? { ...snapshot, groups, retainedEffort } : snapshot
  normalizedEffortSnapshots.set(snapshot, result)
  return result
}

const normalizedEffortDirectories = new WeakMap()
function lowercaseEffortDirectory(directory) {
  if (!directory || typeof directory.getSnapshot !== 'function') return directory
  let wrapped = normalizedEffortDirectories.get(directory)
  if (!wrapped) {
    wrapped = {
      subscribe: listener => directory.subscribe(listener),
      getSnapshot: () => normalizeEffortSnapshot(directory.getSnapshot()),
    }
    normalizedEffortDirectories.set(directory, wrapped)
  }
  return wrapped
}

function isMaxEffortSnapshot(snapshot) {
  const current = snapshot?.current
  if (!current) return false
  for (const group of snapshot.groups ?? []) {
    if (group.id !== current.provider) continue
    const model = group.models?.find(item => item.id === current.model)
    const efforts = model?.reasoning?.efforts
    if (!efforts || efforts.length < 2) return false
    const effective = current.reasoningEffort ?? model.reasoning.defaultEffort
    return effective !== undefined && effective === efforts[efforts.length - 1]?.id
  }
  return false
}

