const QUOTA_PAUSE_KEY = 'dshHostQuotaPause'
const QUOTA_RESUME_DELAY_MS = 120000
const QUOTA_RESUME_MAX_STREAK = 3
const QUOTA_RESUME_STALE_MS = 6 * 3600 * 1000
const QUOTA_PREF_KEY = 'dsh-host.quotaResume.enabled'
// Read-only fallback: the toggle was stored under this key before 2026-11-27.
const LEGACY_QUOTA_PREF_KEY = 'codexhost.quotaResume.enabled'
const quotaClaimKey = (sessionId, seq) => `dsh-host.quotaResume.claim.${sessionId}.${seq}`
// Read-only: claims recorded before 2026-11-27 used this key; honouring them prevents a second automatic resume.
const legacyQuotaClaimKey = (sessionId, seq) => `codexhost.quotaResume.claim.${sessionId}.${seq}`
